// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout, MatrixTriangle } from '@stdlib/types/blas';

/**
* Status code.
*
* ## Notes
*
* The status code indicates the following conditions:
*
* -   if equal to zero, then the factorization was successful.
* -   if greater than zero and equal to `i`, then `D(i,i)` is exactly zero (one-based); the factorization has been completed, but the block diagonal matrix `D` is exactly singular, and division by zero will occur if it is used to solve a system of equations.
*/
type StatusCode = number;

/**
* Interface describing `dsptrf`.
*/
interface Routine {
	/**
	* Computes the factorization of a real symmetric matrix `A` stored in packed format using the Bunch-Kaufman diagonal pivoting method.
	*
	* ## Notes
	*
	* -   `AP` should have `N*(N+1)/2` elements. On exit, `AP` is overwritten by the block diagonal matrix `D` and the multipliers used to obtain the factor `U` or `L`, stored as a packed triangular matrix.
	* -   `IPIV` should have `N` elements and contains details of the interchanges and the block structure of `D` (values are one-based, as in the reference LAPACK implementation).
	*
	* @param order - storage layout
	* @param uplo - specifies whether the upper or lower triangular part of the symmetric matrix `A` is supplied
	* @param N - order of the matrix `A`
	* @param AP - packed form of a symmetric matrix `A`
	* @param IPIV - vector of pivot indices
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var AP = new Float64Array( [ 4.0, 1.0, 2.0, -2.0, 0.0, 3.0, 2.0, 1.0, -2.0, -1.0 ] );
	* var IPIV = new Int32Array( 4 );
	*
	* dsptrf( 'column-major', 'upper', 4, AP, IPIV );
	* // IPIV => <Int32Array>[ 1, 2, 3, 1 ]
	*/
	( order: Layout, uplo: MatrixTriangle, N: number, AP: Float64Array, IPIV: Int32Array ): StatusCode;

	/**
	* Computes the factorization of a real symmetric matrix `A` stored in packed format using the Bunch-Kaufman diagonal pivoting method and alternative indexing semantics.
	*
	* ## Notes
	*
	* -   `AP` should have `N*(N+1)/2` indexed elements. On exit, `AP` is overwritten by the block diagonal matrix `D` and the multipliers used to obtain the factor `U` or `L`, stored as a packed triangular matrix.
	* -   `IPIV` should have `N` indexed elements and contains details of the interchanges and the block structure of `D` (values are one-based, as in the reference LAPACK implementation).
	*
	* @param order - storage layout
	* @param uplo - specifies whether the upper or lower triangular part of the symmetric matrix `A` is supplied
	* @param N - order of the matrix `A`
	* @param AP - packed form of a symmetric matrix `A`
	* @param strideAP - stride length for `AP`
	* @param offsetAP - starting index for `AP`
	* @param IPIV - vector of pivot indices
	* @param strideIPIV - stride length for `IPIV`
	* @param offsetIPIV - starting index for `IPIV`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var AP = new Float64Array( [ 4.0, 1.0, 2.0, -2.0, 0.0, 3.0, 2.0, 1.0, -2.0, -1.0 ] );
	* var IPIV = new Int32Array( 4 );
	*
	* dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV, 1, 0 );
	* // IPIV => <Int32Array>[ 1, 2, 3, 1 ]
	*/
	ndarray( order: Layout, uplo: MatrixTriangle, N: number, AP: Float64Array, strideAP: number, offsetAP: number, IPIV: Int32Array, strideIPIV: number, offsetIPIV: number ): StatusCode;
}

/**
* Computes the factorization of a real symmetric matrix `A` stored in packed format using the Bunch-Kaufman diagonal pivoting method.
*
* ## Notes
*
* -   `AP` should have `N*(N+1)/2` elements. On exit, `AP` is overwritten by the block diagonal matrix `D` and the multipliers used to obtain the factor `U` or `L`, stored as a packed triangular matrix.
* -   `IPIV` should have `N` elements and contains details of the interchanges and the block structure of `D` (values are one-based, as in the reference LAPACK implementation).
*
* @param order - storage layout
* @param uplo - specifies whether the upper or lower triangular part of the symmetric matrix `A` is supplied
* @param N - order of the matrix `A`
* @param AP - packed form of a symmetric matrix `A`
* @param IPIV - vector of pivot indices
* @returns status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var AP = new Float64Array( [ 4.0, 1.0, 2.0, -2.0, 0.0, 3.0, 2.0, 1.0, -2.0, -1.0 ] );
* var IPIV = new Int32Array( 4 );
*
* dsptrf( 'column-major', 'upper', 4, AP, IPIV );
* // IPIV => <Int32Array>[ 1, 2, 3, 1 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var AP = new Float64Array( [ 4.0, 1.0, 2.0, -2.0, 0.0, 3.0, 2.0, 1.0, -2.0, -1.0 ] );
* var IPIV = new Int32Array( 4 );
*
* dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV, 1, 0 );
* // IPIV => <Int32Array>[ 1, 2, 3, 1 ]
*/
declare var dsptrf: Routine;


// EXPORTS //

export = dsptrf;
